/**
 * InvestmentAccountSummary
 */
export type InvestmentAccountSummary = {
  /**
   * Bank Account Id
   */
  bank_account_id: string;
  /**
   * Name
   */
  name: string;
  /**
   * Is Business
   */
  is_business: boolean;
  /**
   * Currency
   */
  currency: string;
  /**
   * Holdings Value
   *
   * What the holdings are worth, in minor units.
   */
  holdings_value: number;
  /**
   * Cash
   *
   * Uninvested cash in the account, in minor units.
   */
  cash: number;
  /**
   * Total
   *
   * Holdings plus cash.
   */
  total: number;
  /**
   * Acquired Value
   *
   * What the current holdings cost, in minor units.
   */
  acquired_value: number;
  /**
   * Deposits
   *
   * All money put into the account, in minor units.
   */
  deposits: number;
  /**
   * Withdrawals
   *
   * All money taken out of the account, in minor units.
   */
  withdrawals: number;
  /**
   * Net Deposits
   *
   * Deposits minus withdrawals.
   */
  net_deposits: number;
  /**
   * Growth
   *
   * Total minus net deposits: what the account made or lost overall.
   */
  growth: number;
  /**
   * Dividends
   *
   * Dividends received per year, newest first.
   */
  dividends: Array<YearAmount>;
  /**
   * Interest
   *
   * Interest per year, newest first; below zero when paying it on a loan.
   */
  interest: Array<YearAmount>;
  /**
   * Tax
   *
   * Tax per year, such as a KF's yield tax, newest first; below zero.
   */
  tax: Array<YearAmount>;
  /**
   * Fees
   *
   * Fees per year, newest first; below zero.
   */
  fees: Array<YearAmount>;
  /**
   * First Transaction
   */
  first_transaction: Date | null;
};

